float aspect = resolution.x / resolution.y;
vec2 p = vec2(uv.x * aspect, uv.y);
float t = time * (0.02 + 0.1 * param[2]);

// A curl-noise flow: the sky's restless currents, which never pool.
vec2 np = p * 1.6 + vec2(t, -0.6 * t);
float e = 0.03;
float dx = valueNoise(np + vec2(e, 0.0)) - valueNoise(np - vec2(e, 0.0));
float dy = valueNoise(np + vec2(0.0, e)) - valueNoise(np - vec2(0.0, e));
vec2 flow = vec2(dy, -dx) / (2.0 * e);

// The painting's long bands: the whole sky leans left to right, in a slow wave.
flow += vec2(1.0, 0.5 * sin(p.x * 3.0 + t * 4.0)) * 0.8;

// Two vortices where the painting has them: the big double spiral and its smaller twin.
vec2 c1 = vec2(0.5 * aspect, 0.66);
vec2 c2 = vec2(0.69 * aspect, 0.5);
vec2 d1 = p - c1;
vec2 d2 = p - c2;
float pull1 = exp(-dot(d1, d1) * 12.0);
float pull2 = exp(-dot(d2, d2) * 40.0);
float kick = audio.beat;
flow = flow * 0.5 + (vec2(-d1.y, d1.x) / (length(d1) + 0.02) * pull1 + vec2(d2.y, -d2.x) / (length(d2) + 0.02) * pull2) * (1.0 + 3.0 * param[0]);
vec2 dir = normalize(flow + vec2(0.0001, 0.0));
vec2 dirUv = vec2(dir.x / aspect, dir.y);

// Twist the picture about each centre; the kick winds the spiral tighter.
float turn = strength * (0.5 + 2.5 * param[0] + 1.2 * kick);
float a1 = pull1 * turn + 0.15 * sin(t * 6.0);
float a2 = -pull2 * turn;
vec2 q = c1 + mat2(cos(a1), sin(a1), -sin(a1), cos(a1)) * d1;
q = c2 + mat2(cos(a2), sin(a2), -sin(a2), cos(a2)) * (q - c2);
vec2 base = vec2(q.x / aspect, q.y) + dirUv * 0.012 * strength;

// Brushstrokes: the picture and a fine noise both averaged along the flow (a line integral
// convolution), so the noise turns into short parallel streaks that follow the current.
float reach = 0.015 + 0.05 * param[1];
vec3 col = vec3(0.0);
float streak = 0.0;
for (int i = 0; i < 6; i++) {
  float s = float(i) / 5.0 - 0.5;
  col += source(base + dirUv * reach * strength * s * 0.6);
  streak += valueNoise((p + dir * reach * s) * 120.0);
}
col /= 6.0;
streak = clamp((streak / 6.0 - 0.5) * 3.0 + 0.5, 0.0, 1.0);
col *= mix(1.0, 0.62 + 0.75 * streak, strength);

// The kick lights the spiral's arms for a moment.
col += palette[3] * pull1 * kick * 0.3 * strength * streak;

// Wet paint: the last frame carried a little way along the current.
vec3 before = lastFrame(uv - dirUv * 0.004);
return mix(col, before, 0.35 * strength);

float aspect = resolution.x / resolution.y;
vec2 p = vec2(uv.x * aspect, uv.y);
vec3 col = source(uv);
vec3 core = palette[paletteSize - 2];
vec3 glow = palette[paletteSize - 1];

// Stars on a jittered grid, only in the sky, each in its own ringed halo.
float cells = 3.0 + 5.0 * param[0];
vec2 g = p * cells;
vec2 cell = floor(g);
float light = 0.0;
float rings = 0.0;
for (int j = -1; j <= 1; j++) {
  for (int i = -1; i <= 1; i++) {
    vec2 id = cell + vec2(float(i), float(j));
    float h = hash(id);
    vec2 pos = id + 0.2 + 0.6 * vec2(hash(id + 7.1), hash(id + 3.7));
    float sky = smoothstep(0.5, 0.7, pos.y / cells);
    if (h < 0.4 || sky <= 0.0) {
      continue;
    }
    float d = length(g - pos) / cells;
    float size = 0.012 + 0.016 * hash(id + 1.3);
    float twinkle = 0.75 + 0.25 * sin(time * (1.0 + 2.0 * h) + h * 40.0) + 0.9 * audio.high;
    light += exp(-d * d / (size * size)) * twinkle * sky;
    rings += exp(-d / (size * 3.5)) * (0.5 + 0.5 * cos(d * 200.0 - time * 1.5)) * twinkle * sky;
  }
}

// The crescent moon top right, with the widest halo of all.
vec2 m = vec2(aspect - 0.13, 0.82);
float md = length(p - m);
float moon = smoothstep(0.065, 0.058, md) * smoothstep(0.045, 0.052, length(p - m - vec2(-0.025, 0.02)));
float moonHalo = exp(-md / 0.1) * (0.5 + 0.5 * cos(md * 130.0 - time * 0.8));

vec3 add = core * (light + moon * 1.4) + glow * (rings + moonHalo) * param[1];
return col * (1.0 - 0.6 * moon * strength) + add * strength;
